        for shape,er,ec in opts:
            if pts<=shape and len(shape-pts)<=1 and len(pts)>=6:
                guides.append((len(pts),color,er,ec));break
    if not guides:return [row[:] for row in grid]
    _,paint,er,ec=max(guides)
    # Recolor the separate object on the guide's vertical axis, irrespective of gap.
    options=[]
    for color,cells in comps:
        if color==paint:continue
        aligned=[r for r,c in cells if c==ec]
        if aligned: options.append((min(abs(r-er) for r in aligned),cells))
    if not options:return [row[:] for row in grid]
    _,target=min(options,key=lambda x:x[0])
    out=[row[:] for row in grid]
    for r,c in target:out[r][c]=paint
